import React, { useState, useEffect } from 'react'
import { Swiper, SwiperSlide } from 'swiper/react';
import { Navigation } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/navigation';
import '../css/swiperCss.css';
import { useTranslation } from 'react-i18next'

const SwiperItems = ({ items, renderItems }) => {

  const { i18n } = useTranslation()
  const dir = i18n.dir()

  const [currentIndex, setCurrentIndex] = useState(0)
  const [itemsPerPage, setItemsPerPage] = useState(1)

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 1200) { // xl breakpoint
        setItemsPerPage(4)
      } else if (window.innerWidth >= 992) { // lg breakpoint
        setItemsPerPage(3)
      } else if (window.innerWidth >= 768) { // md breakpoint
        setItemsPerPage(2)
      } else {
        setItemsPerPage(1)
      }
    }

    handleResize() // Set initial value
    window.addEventListener('resize', handleResize)

    return () => {
      window.removeEventListener('resize', handleResize)
    }
  }, [])

  const nextItems = () => {
    if (currentIndex + 1 < items.length - (itemsPerPage - 1)) {
      setCurrentIndex(currentIndex + 1)
    }
  }

  const previousItems = () => {
    if (currentIndex - 1 >= 0) {
      setCurrentIndex(currentIndex - 1)
    }
  }

  return (
    <>
      {items && items.length > 0 && items.length > itemsPerPage && (
        <div className="d-flex justify-content-between">
          <div className="pr-5">
            {currentIndex > 0 && (
              <button
                className="btn position-relative top-50 end-0 translate-middle-y"
                onClick={previousItems}
              >
                {dir === 'rtl' ? <i className="bi bi-arrow-right-square-fill" style={{ fontSize: '3rem' }}></i> : <i className="bi bi-arrow-left-square-fill" style={{ fontSize: '3rem' }}></i>}
              </button>
            )}
          </div>
          <div className="pl-5">
            {currentIndex < items.length - itemsPerPage && (
              <button
                className="btn position-relative top-50 start-0 translate-middle-y"
                onClick={nextItems}
              >
                {dir === 'rtl' ? <i className="bi bi-arrow-left-square-fill" style={{ fontSize: '3rem' }}></i> : <i className="bi bi-arrow-right-square-fill" style={{ fontSize: '3rem' }}></i>}
              </button>
            )}
          </div>
        </div>
      )}
        <div className="row row-cols-md-2 row-cols-lg-3 row-cols-xl-4 g-4 p-4"  >
          {items && items.length > 0 ? (
            <>
              {items.slice(currentIndex, currentIndex + itemsPerPage).map((item, index) => (
                renderItems(item, index)
              ))}
            </>
          ) : (
            <h1>לא נמצאו פריטים</h1>
          )}
        </div>
    </>
  )
}

export default SwiperItems